import React from 'react';
import { AbsoluteFill, useCurrentFrame, useVideoConfig } from 'remotion';
import { Activity, Zap } from 'lucide-react';
import { label, beats } from './labels';
import { brand } from './theme';
import { state } from './store';
import { clamp } from './util';

export default function HotModuleApp() {
  const frame = useCurrentFrame();
  const { durationInFrames } = useVideoConfig();
  const progress = Math.min(1, frame / durationInFrames);

  return (
    <AbsoluteFill style={{ backgroundColor: '#020617', alignItems: 'center', justifyContent: 'center', fontFamily: 'Arial, sans-serif', color: '#f8fafc' }}>
      <div style={{ fontFamily: 'monospace', letterSpacing: 3, fontSize: 14, color: '#a78bfa', marginBottom: 18 }}>
        VFS MODULE GRAPH · HMR UPDATE
      </div>
      <div style={{ fontSize: 54, fontWeight: 900, letterSpacing: -1 }}>
        {label}
      </div>
      <div style={{ display: 'flex', gap: 14, marginTop: 22, fontFamily: 'monospace', fontSize: 15 }}>
        <div style={{ padding: '10px 16px', borderRadius: 10, border: '1px solid #1e293b', color: '#67e8f9' }}>
          theme: {brand.name}
        </div>
        <div style={{ padding: '10px 16px', borderRadius: 10, border: '1px solid #1e293b', color: '#fbbf24' }}>
          beats: {beats} bpm
        </div>
        <div style={{ padding: '10px 16px', borderRadius: 10, border: '1px solid #1e293b', color: '#34d399' }}>
          state: {state.playing ? 'playing' : 'paused'}
        </div>
        <div style={{ padding: '10px 16px', borderRadius: 10, border: '1px solid #1e293b', color: '#f472b6' }}>
          clamp(0.37) = {clamp(0.37)}
        </div>
      </div>
      <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginTop: 26, fontFamily: 'monospace', fontSize: 13, color: '#64748b' }}>
        <Activity style={{ width: 14, height: 14, color: '#22d3ee' }} />
        frame {frame} / {durationInFrames}
        <Zap style={{ width: 14, height: 14, color: '#f59e0b' }} />
        recompiled: app + changed leaf only
      </div>
      <div style={{ marginTop: 10, width: 420, height: 6, borderRadius: 999, backgroundColor: '#1e293b', overflow: 'hidden' }}>
        <div style={{ width: `${progress * 100}%`, height: '100%', borderRadius: 999, background: 'linear-gradient(90deg,#22d3ee,#a78bfa)' }} />
      </div>
    </AbsoluteFill>
  );
}

